const ee = require('@google/earthengine');
const privateKey = require('./.earthsense-436113-b294c5f5c2dc.json');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Define the region of interest (Canada) using FAO GAUL.
    const canada = ee.FeatureCollection('FAO/GAUL/2015/level0')
      .filter(ee.Filter.eq('ADM0_NAME', 'Canada'))
      .first()
      .geometry();

    // Define the start and end days of the year for the comparison period (Jan 1 to Aug 3).
    const startDay = 1; // January 1st
    // Day of the year for August 3rd.
    // In a non-leap year: Jan(31)+Feb(28)+Mar(31)+Apr(30)+May(31)+Jun(30)+Jul(31)+Aug(3) = 215
    const endDay = ee.Date.fromYMD(2023, 8, 3).getRelative('day', 'year').add(1).getInfo(); // Day of year (1-indexed)

    const year2023 = 2023;
    const year2025 = 2025; // Note: 2025 data is in the future. This query will likely result in C1.

    // Define date ranges for MODIS MCD64A1.
    // MCD64A1 is monthly, so we need to fetch all months up to August.
    const startDate2023 = ee.Date.fromYMD(year2023, 1, 1);
    const endDate2023 = ee.Date.fromYMD(year2023, 8, 3).advance(1, 'month').getRange('month'); // Get images up to and including August

    const startDate2025 = ee.Date.fromYMD(year2025, 1, 1);
    const endDate2025 = ee.Date.fromYMD(year2025, 8, 3).advance(1, 'month').getRange('month');

    // 2. Data Acquisition & Check

    // Function to get burned area for a given year and period
    const getBurnedArea = async (year, startDate, endDate, geometry, startDay, endDay) => {
      const collection = ee.ImageCollection('MODIS/051/MCD64A1')
        .filterDate(startDate, endDate)
        .filterBounds(geometry);

      const colSize = await collection.size().getInfo();
      if (colSize === 0) {
        return {
          totalBurnedAreaSqKm: null,
          pixelCount: 0,
          imageCount: 0
        };
      }

      // Create a single image representing the maximum BurnDate for the period
      // (This correctly handles areas burned once across multiple months in the collection)
      const burnedDateImage = collection.select('BurnDate').max();

      // Mask pixels outside the desired day-of-year range or not burned
      const annualBurnedMask = burnedDateImage
        .gte(startDay)
        .and(burnedDateImage.lte(endDay))
        .updateMask(burnedDateImage.neq(0)); // Ensure only actual burned pixels are considered

      // Calculate area of each pixel (MCD64A1 is 500m resolution)
      const pixelAreaSqKm = ee.Image.pixelArea().divide(1e6); // Convert m^2 to km^2

      // Multiply the mask by pixel area to get burned area per pixel
      const burnedAreaPerPixel = annualBurnedMask.multiply(pixelAreaSqKm);

      // Reduce region to get total burned area and pixel count
      const reducer = ee.Reducer.sum().unweighted(); // sum of km^2
      const pixelCountReducer = ee.Reducer.count(); // count of valid pixels

      const stats = await burnedAreaPerPixel.reduceRegion({
        reducer: reducer.combine({
          reducer2: pixelCountReducer,
          sharedInputs: true
        }),
        geometry: geometry,
        scale: 500, // MCD64A1 resolution
        maxPixels: 1e9,
        crs: 'EPSG:4326', // Use WGS84 CRS for area calculations for consistency
        tileScale: 4
      }).getInfo();

      const totalBurnedAreaSqKm = stats ? stats['sum'] : null;
      const pixelCount = stats ? stats['count'] : 0;

      return {
        totalBurnedAreaSqKm: totalBurnedAreaSqKm,
        pixelCount: pixelCount,
        imageCount: colSize
      };
    };

    console.log(`Comparing burned area from Jan 1 to Aug 3 for ${year2023} and ${year2025}.`);
    console.log(`Target day-of-year range: ${startDay}-${endDay}`);

    const result2023 = await getBurnedArea(year2023, startDate2023, endDate2023, canada, startDay, endDay);
    console.log(`2023 Images: ${result2023.imageCount}, Pixels: ${result2023.pixelCount}`);

    const result2025 = await getBurnedArea(year2025, startDate2025, endDate2025, canada, startDay, endDay);
    console.log(`2025 Images: ${result2025.imageCount}, Pixels: ${result2025.pixelCount}`);

    // 3. Validation and Fallback Checks
    if (result2023.imageCount === 0 || result2025.imageCount === 0) {
      console.log('Empty Collection (No images found for one or both comparison points)');
      console.log('C1');
      return;
    }

    if (result2023.pixelCount === 0 || result2025.pixelCount === 0) {
      console.log('No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain)');
      console.log('C2');
      return;
    }

    const burnedArea2023 = result2023.totalBurnedAreaSqKm;
    const burnedArea2025 = result2025.totalBurnedAreaSqKm;

    if (burnedArea2023 === null || burnedArea2025 === null || isNaN(burnedArea2023) || isNaN(burnedArea2025)) {
      console.log('Calculation Failure (Result is None, NaN, or invalid)');
      console.log('C3');
      return;
    }

    // 4. Comparison and Final Answer
    console.log(`2023 Burned Area: ${burnedArea2023.toFixed(2)} sq km`);
    console.log(`2025 Burned Area: ${burnedArea2025.toFixed(2)} sq km`);

    if (burnedArea2025 > burnedArea2023) {
      console.log('A');
    } else {
      console.log('B');
    }

  } catch (e) {
    console.error('An error occurred during analysis:', e);
    console.log('D'); // General error for syntax, method, memory, etc.
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
